import { Ionicons } from '@expo/vector-icons';
import { useRouter } from 'expo-router';
import { useMemo, useState } from 'react';
import {
  FlatList,
  Modal,
  Platform,
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  useColorScheme,
  View,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

// Import the scraped JSON file generated by scripts/scrape-kgbus.ts
import TIMETABLES_DATA from '../../data/timetables.json';

// ============================================================================
// TYPES
// ============================================================================
interface DirectionSchedule {
  directionName: string;
  workday: string[];
  saturday: string[];
  sunday: string[];
}

interface LineTimetable {
  id: string;
  lineNumber: string;
  route: string;
  directionA: DirectionSchedule;
  directionB: DirectionSchedule;
}

type DayType = 'workday' | 'saturday' | 'sunday';
type DirectionType = 'A' | 'B';

// ============================================================================
// RESPONSIVE THEME PALETTE (Matches index.tsx + Device Theme)
// ============================================================================
const LightTheme = {
  background: '#F4F7FA',
  surface: '#FFFFFF',
  surfaceBorder: '#E2E8F0',
  surfaceElevated: '#F1F5F9',
  textPrimary: '#111827',
  textSecondary: '#4B5563',
  textMuted: '#6B7280',
  accentBlue: '#1A56DB',
  accentBluePressed: '#1545B3',
  accentBlueSoft: '#EFF6FF',
  chevron: '#9CA3AF',
  backdrop: 'rgba(15, 23, 42, 0.5)',
  chipBg: '#F1F5F9',
  chipBorder: '#E2E8F0',
  nextTimeBg: '#DBEAFE',
  nextTimeBorder: '#2563EB',
  nextTimeText: '#1D4ED8',
};

const DarkTheme = {
  background: '#0F172A',
  surface: '#1E293B',
  surfaceBorder: '#334155',
  surfaceElevated: '#0F172A',
  textPrimary: '#F8FAFC',
  textSecondary: '#CBD5E1',
  textMuted: '#94A3B8',
  accentBlue: '#3B82F6',
  accentBluePressed: '#2563EB',
  accentBlueSoft: 'rgba(59, 130, 246, 0.16)',
  chevron: '#64748B',
  backdrop: 'rgba(0, 0, 0, 0.72)',
  chipBg: '#0F172A',
  chipBorder: '#334155',
  nextTimeBg: 'rgba(59, 130, 246, 0.25)',
  nextTimeBorder: '#3B82F6',
  nextTimeText: '#93C5FD',
};

export default function TimetablesScreen() {
  const colorScheme = useColorScheme();
  const isDark = colorScheme === 'dark';
  const theme = isDark ? DarkTheme : LightTheme;
  const router = useRouter();

  const [selectedLine, setSelectedLine] = useState<LineTimetable | null>(null);
  const [selectedDay, setSelectedDay] = useState<DayType>('workday');
  const [selectedDirection, setSelectedDirection] = useState<DirectionType>('A');

  const lines = TIMETABLES_DATA as LineTimetable[];

  // Identify the next upcoming departure time to highlight it in the grid
  const nextDepartureTime = useMemo(() => {
    if (!selectedLine) return null;
    const schedule =
      selectedDirection === 'A'
        ? selectedLine.directionA[selectedDay]
        : selectedLine.directionB[selectedDay];

    const now = new Date();
    const currentMinutes = now.getHours() * 60 + now.getMinutes();

    return (
      schedule.find((timeStr) => {
        const [h, m] = timeStr.split(':').map(Number);
        return h * 60 + m >= currentMinutes;
      }) || null
    );
  }, [selectedLine, selectedDay, selectedDirection]);

  const openLineModal = (line: LineTimetable) => {
    // Automatically default day tab to today's day of the week
    const dayOfWeek = new Date().getDay(); // 0 = Sun, 6 = Sat
    if (dayOfWeek === 0) setSelectedDay('sunday');
    else if (dayOfWeek === 6) setSelectedDay('saturday');
    else setSelectedDay('workday');

    setSelectedDirection('A');
    setSelectedLine(line);
  };

  const renderLineCard = ({ item }: { item: LineTimetable }) => (
    <Pressable
      onPress={() => openLineModal(item)}
      android_ripple={{
        color: isDark ? 'rgba(255,255,255,0.08)' : 'rgba(0,0,0,0.05)',
      }}
      style={({ pressed }) => [
        styles.card,
        {
          backgroundColor: theme.surface,
          borderColor: isDark ? theme.surfaceBorder : 'transparent',
          borderWidth: isDark ? 1 : 0,
          opacity: Platform.OS === 'ios' && pressed ? 0.9 : 1,
        },
      ]}
    >
      <View style={styles.cardLeft}>
        <Text style={[styles.lineNumber, { color: theme.accentBlue }]}>
          {item.lineNumber}
        </Text>
        <Text
          style={[styles.routeText, { color: theme.textSecondary }]}
          numberOfLines={2}
        >
          {item.route}
        </Text>
      </View>

      <Ionicons name="chevron-forward" size={18} color={theme.chevron} />
    </Pressable>
  );

  const activeDirectionObj =
    selectedLine &&
    (selectedDirection === 'A'
      ? selectedLine.directionA
      : selectedLine.directionB);

  const activeTimes = activeDirectionObj ? activeDirectionObj[selectedDay] : [];

  return (
    <SafeAreaView
      style={[styles.container, { backgroundColor: theme.background }]}
      edges={['top', 'left', 'right']}
    >
      {/* Top Header matching the screenshot */}
      <View style={styles.headerRow}>
        <Text style={[styles.headerTitle, { color: theme.textPrimary }]}>
          Red vožnje
        </Text>

        <Pressable
          onPress={() => router.back()}
          android_ripple={{ color: 'rgba(255,255,255,0.2)' }}
          style={({ pressed }) => [
            styles.backButton,
            {
              backgroundColor: pressed
                ? theme.accentBluePressed
                : theme.accentBlue,
            },
          ]}
        >
          <Text style={styles.backButtonText}>Nazad</Text>
        </Pressable>
      </View>

      {/* Bus Lines List */}
      <FlatList
        data={lines}
        keyExtractor={(item) => item.id}
        renderItem={renderLineCard}
        contentContainerStyle={styles.listContent}
        showsVerticalScrollIndicator={false}
      />

      {/* Bottom Sheet Modal for Selected Line Timetable */}
      <Modal
        visible={!!selectedLine}
        animationType="slide"
        transparent
        onRequestClose={() => setSelectedLine(null)}
      >
        <View style={[styles.modalOverlay, { backgroundColor: theme.backdrop }]}>
          {/* Dismiss when tapping backdrop */}
          <Pressable
            style={styles.backdropDismiss}
            onPress={() => setSelectedLine(null)}
          />

          <View
            style={[
              styles.bottomSheet,
              {
                backgroundColor: theme.surface,
                borderColor: theme.surfaceBorder,
              },
            ]}
          >
            {/* Bottom Sheet Grab Handle */}
            <View style={styles.sheetHandleRow}>
              <View
                style={[
                  styles.sheetHandle,
                  { backgroundColor: theme.surfaceBorder },
                ]}
              />
            </View>

            {selectedLine && (
              <>
                {/* Sheet Header */}
                <View style={styles.sheetHeader}>
                  <View style={styles.sheetTitleBlock}>
                    <View style={styles.sheetLineBadgeRow}>
                      <View
                        style={[
                          styles.sheetLineBadge,
                          { backgroundColor: theme.accentBlueSoft },
                        ]}
                      >
                        <Text
                          style={[
                            styles.sheetLineNumber,
                            { color: theme.accentBlue },
                          ]}
                        >
                          Linija {selectedLine.lineNumber}
                        </Text>
                      </View>
                      <Text
                        style={[
                          styles.sourceTag,
                          { color: theme.textMuted },
                        ]}
                      >
                        kgbus.rs
                      </Text>
                    </View>
                    <Text
                      style={[
                        styles.sheetRouteTitle,
                        { color: theme.textPrimary },
                      ]}
                    >
                      {selectedLine.route}
                    </Text>
                  </View>

                  <Pressable
                    onPress={() => setSelectedLine(null)}
                    hitSlop={10}
                    style={[
                      styles.closeIconButton,
                      { backgroundColor: theme.surfaceElevated },
                    ]}
                  >
                    <Ionicons
                      name="close"
                      size={20}
                      color={theme.textSecondary}
                    />
                  </Pressable>
                </View>

                {/* Direction Toggle (Smer A / Smer B) */}
                <View
                  style={[
                    styles.segmentedContainer,
                    { backgroundColor: theme.surfaceElevated },
                  ]}
                >
                  {(['A', 'B'] as DirectionType[]).map((dir) => {
                    const isActive = selectedDirection === dir;
                    return (
                      <Pressable
                        key={dir}
                        onPress={() => setSelectedDirection(dir)}
                        style={[
                          styles.segmentButton,
                          isActive && {
                            backgroundColor: theme.accentBlue,
                          },
                        ]}
                      >
                        <Text
                          style={[
                            styles.segmentText,
                            {
                              color: isActive
                                ? '#FFFFFF'
                                : theme.textSecondary,
                            },
                          ]}
                        >
                          {dir === 'A' ? 'Smer A' : 'Smer B'}
                        </Text>
                      </Pressable>
                    );
                  })}
                </View>

                {/* Active Direction Subtitle */}
                {activeDirectionObj && (
                  <Text
                    style={[
                      styles.directionSubtitle,
                      { color: theme.textMuted },
                    ]}
                  >
                    {activeDirectionObj.directionName}
                  </Text>
                )}

                {/* Day Selector Tabs (Radni dan / Subota / Nedelja) */}
                <View style={styles.dayTabsRow}>
                  {(
                    [
                      { key: 'workday', label: 'Radni dan' },
                      { key: 'saturday', label: 'Subota' },
                      { key: 'sunday', label: 'Nedelja' },
                    ] as { key: DayType; label: string }[]
                  ).map((tab) => {
                    const active = selectedDay === tab.key;
                    return (
                      <Pressable
                        key={tab.key}
                        onPress={() => setSelectedDay(tab.key)}
                        style={[
                          styles.dayTab,
                          {
                            borderColor: active
                              ? theme.accentBlue
                              : theme.surfaceBorder,
                            backgroundColor: active
                              ? theme.accentBlueSoft
                              : 'transparent',
                          },
                        ]}
                      >
                        <Text
                          style={[
                            styles.dayTabText,
                            {
                              color: active
                                ? theme.accentBlue
                                : theme.textSecondary,
                            },
                          ]}
                        >
                          {tab.label}
                        </Text>
                      </Pressable>
                    );
                  })}
                </View>

                {/* Departure Times Grid */}
                <ScrollView
                  style={styles.timesScroll}
                  contentContainerStyle={styles.timesGrid}
                  showsVerticalScrollIndicator={false}
                >
                  {activeTimes.length > 0 ? (
                    activeTimes.map((time, idx) => {
                      const isNext = time === nextDepartureTime;
                      return (
                        <View
                          key={`${time}-${idx}`}
                          style={[
                            styles.timeChip,
                            {
                              backgroundColor: isNext
                                ? theme.nextTimeBg
                                : theme.chipBg,
                              borderColor: isNext
                                ? theme.nextTimeBorder
                                : theme.chipBorder,
                            },
                          ]}
                        >
                          <Text
                            style={[
                              styles.timeText,
                              {
                                color: isNext
                                  ? theme.nextTimeText
                                  : theme.textPrimary,
                              },
                            ]}
                          >
                            {time}
                          </Text>
                        </View>
                      );
                    })
                  ) : (
                    <Text
                      style={[styles.emptyText, { color: theme.textMuted }]}
                    >
                      Nema zakazanih polazaka za izabrani dan.
                    </Text>
                  )}
                </ScrollView>
              </>
            )}
          </View>
        </View>
      </Modal>
    </SafeAreaView>
  );
}

